SELECT  FROM health_record
WHERE user_id = #{userId}
ORDER BY record_time DESC
LIMIT #{limit}

SELECT  FROM health_record
WHERE user_id = #{userId}
  AND record_time BETWEEN #{dayStart} AND #{dayEnd}
ORDER BY record_time DESC

SELECT  FROM health_record
WHERE create_time BETWEEN #{start} AND #{end}
ORDER BY record_time DESC
